import api from '../utils/api';
import { PRODUCTS, CATEGORIES } from '../utils/dummyData';

export const productService = {
  async getProducts(params = {}) {
    try {
      const { data } = await api.get('/products', { params });
      return data.data;
    } catch (error) {
      console.warn('API Error, using dummy products:', error.message);
      return { items: PRODUCTS, total: PRODUCTS.length };
    }
  },
  async getProductById(id) {
    try {
      const { data } = await api.get(`/products/${id}`);
      return data.data.item;
    } catch (error) {
      console.warn('API Error, using dummy product:', error.message);
      return PRODUCTS.find(p => p._id === id);
    }
  },
  async getCategories() {
    try {
      const { data } = await api.get('/categories');
      return data.data.items;
    } catch (error) {
      console.warn('API Error, using dummy categories:', error.message);
      return CATEGORIES.map((c, i) => ({ ...c, _id: `cat-${i}` }));
    }
  }
};
